document.addEventListener("DOMContentLoaded",function(){const t=document.querySelectorAll(".tab-btn"),e=document.querySelectorAll(".btn-continue"),n=document.querySelectorAll(".btn-secondary");t.forEach(e=>{e.addEventListener("click",function(){t.forEach(t=>t.classList.remove("active")),this.classList.add("active");this.getAttribute("data-tab");showToast(`Affichage: ${this.textContent.trim()}`,"info")})}),e.forEach(t=>{t.addEventListener("click",function(){const t=this.closest(".aide-card").querySelector(".aide-info h3").textContent;showToast(`Ouverture de la conversation: ${t}`,"info")})}),n.forEach(t=>{t.addEventListener("click",function(){const t=this.textContent.trim();showToast(`${t} - En cours...`,"info")})})});